// TH14 funcCall 6: one drum cue releases each waiting bullet once.
// The attack owns `channel` (0..7) and calls pulse_signal(channel) at the original drum times.
// Native source has no competing continuous turn/acceleration on these bullets.
// rand is sampled per bullet at release, not once when the shooter is configured.
xformdef TH14_DRUM_ONCE(channel: int) {
    wait_signal(channel);
    @60 set_accel(at_effect(((rand(65536) - 32768) as fx) / 32768 * 0.01fx));
    set_accel(0fx);
}

const TIME_LIMIT: int = 3424;
const OPENING_BUFFER: int = 120;
const TH14_BULLET: int = 560; // TH14 native type13, approved modern catalog alias.

// Enemy int0=movement step; fx0/1=direction. Source ABS only, limit280x64.
sub arm_move() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var v: fx = 0fx;
    if k < 60 { v = 0.6fx*(60-k)/60; }
    var nx: fx = $self_x+self_fx(0)*v;
    var ny: fx = $self_y+self_fx(1)*v;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub drum_move_rand() {
    // Shared modern moveRand recipe; inner quarter-width70, y112..144.
    // Source moveVelTime(0,0,0,0) establishes linear speed mode before this loop.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx { a = r/3; }
    else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else { if choose != 0 { a = a+32768; } }
    }
    if $self_y < 112fx { if a < 0 { a = -a; } }
    else if $self_y > 144fx { if a < 0 { a = -a; } a = -a; }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
}
sub emit_ring() {
    // BossCard4_at: etNew every90; etAim3,140x1,speed1; source delta1deg is
    // a layer rotation and has no effect for M=1. Three source random reads.
    sh_reset(0);
    sh_sprite(0, TH14_BULLET, 13);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 140, 1);
    sh_angle(0, (rand(65536)-32768) as angle, 1deg);
    sh_speed(0, 1fx, 0fx);
    sh_xform(0, TH14_DRUM_ONCE(0));
    var offset_angle: angle = (rand(65536)-32768) as angle;
    var radius: fx = (rand(65536)-32768) as fx / 32768 * 32fx;
    sh_offset(0, cos(offset_angle)*radius, sin(offset_angle)*radius);
    sh_fire(0);
}
async sub boss() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    // BossCard4 timerReset is source frame0; prior-wave clear has no old bullets.
    // Source entry movePosTime(60,4,0,144), inherited Boss position(0,128).
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(150); // source60 charge +90; presentation-only charge/sounds omitted.
    set_self_int(0, 60);
    var next_ring: int = 150;
    var next_drum: int = 310; // source150+wait160; then wait80+wait160.
    for t in 150..3000 {
        // Source async starts at script150; merge its independent90 cadence here
        // without adding target async startup delay or changing its birth positions.
        if t == next_ring { emit_ring(); next_ring = next_ring+90; }
        if t == next_drum {
            drum_move_rand();
            pulse_signal(0); // original funcCall6, exclusively owned channel0.
            next_drum = next_drum+240;
        }
        // Prepare next source movement tick after the current ECL/fire reads.
        arm_move();
        wait(1);
    }
    // Source timeout3000 stops the attack, never enters Boss5. Tail budget
    // does not permit more shots, pulses, or another attack.
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    wait(300);
}
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 3500, 0, 0, 0, boss);
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
